from hermes_tools import terminal
script = r'''
from openpyxl import load_workbook
from openpyxl.utils import get_column_letter
wb=load_workbook('/root/data/workbook.xlsx', data_only=False)
ws=wb['Data']
print('Data all non-empty rows:')
for r in range(1, ws.max_row+1):
    vals=[]
    for c in range(1, ws.max_column+1):
        v=ws.cell(r,c).value
        if v is not None:
            vals.append(f'{get_column_letter(c)}{r}={v!r}')
    if vals:
        print(f'Row {r}: ' + '; '.join(vals))
# find rows containing years 2020-2024
print('\nRows/cells containing 2020-2024:')
for r in range(1, ws.max_row+1):
    hits=[]
    for c in range(1, ws.max_column+1):
        if ws.cell(r,c).value in [2020,2021,2022,2023,2024,'2020','2021','2022','2023','2024']:
            hits.append(f'{get_column_letter(c)}{r}={ws.cell(r,c).value!r}')
    if hits: print('; '.join(hits))
'''
res=terminal('python3 - <<\'PY\'\n'+script+'\nPY', timeout=300, workdir='/root')
print(res['output'])
if res['exit_code']!=0: raise SystemExit(res['exit_code'])
